import os
import sys
import requests
import time
from threading import Lock

PACKAGES_TOKEN = os.getenv('PACKAGES_TOKEN')
if not PACKAGES_TOKEN:
    sys.exit(1)

def fetch_package_info(name):
    headers = {'Authorization': f'Bearer {PACKAGES_TOKEN}'}
    url = f'https://packages.example.com/api/v1/packages/{name}'
    try:
        response = requests.get(url, headers=headers, timeout=5)
        if response.status_code == 200:
            data = response.json()
            return name, data.get('version', 'not-found'), data.get('license', 'not-found')
        else:
            return name, 'error', str(response.status_code)
    except requests.exceptions.RequestException:
        return name, 'error', 'timeout'

def process_packages():
    package_names = [line.strip() for line in sys.stdin if line.strip()]
    last_request_time = 0
    lock = Lock()
    results = []

    for name in package_names:
        current_time = time.time()
        if current_time - last_request_time < 1.0:
            time.sleep(1.0 - (current_time - last_request_time))
            last_request_time = current_time

        with lock:
            name_info = fetch_package_info(name)
            results.append(name_info)

    for name, version, license in results:
        if name_info[1] == 'error':
            print(f"{name}\t{name_info[2]}\t{name_info[2]}")
        else:
            print(f"{name}\t{version}\t{license}")

if __name__ == '__main__':
    process_packages()

