import os
import sys
import requests
import time
from concurrent.futures import ThreadPoolExecutor, as_completed

def fetch_package_info(name):
    url = f"https://packages.example.com/api/v1/packages/{name}"
    headers = {"Authorization": f"Bearer {os.getenv('PACKAGES_TOKEN')}"}
    try:
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            data = response.json()
            return f"{name}\t{data.get('version', 'unknown')}"
        else:
            return f"{name}\terror\t{response.status_code}"
    except Exception as e:
        return f"{name}\terror\t{500}"

def process_packages():
    package_names = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            package_names.append(line)

    with ThreadPoolExecutor(max_workers=5) as executor:
        futures = []
        start_time = time.time()
        for name in package_names:
            futures.append(executor.submit(fetch_package_info, name))

        results = []
        for future in as_completed(futures):
            results.append(future.result())
            current_time = time.time()
            if len(results) >= 5 and (current_time - start_time) * 1000 >= 1000:
                start_time = current_time
                yield from results
                results = []
        if results:
            yield from results

if __name__ == "__main__":
    for line in process_packages():
        print(line)

import os
import time
import requests
import sys

def main():
    token = os.getenv('PACKAGES_TOKEN')
    if not token:
        sys.exit(1)

    package_names = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            package_names.append(line)

    for i, package in enumerate(package_names):
        start_time = time.time()
        url = f"https://packages.example.com/api/v1/packages/{package}"
        headers = {'Authorization': f'Bearer {token}'}

        try:
            response = requests.get(url, headers=headers)
            elapsed = (time.time() - start_time) * 1000  # milliseconds
            if elapsed < 200:
                time.sleep((0.2 - elapsed / 1000) + 0.001)  # small buffer to avoid timing issues

            if response.status_code == 200:
                data = response.json()
                print(f"{package}\t{data.get('version', '')}")
            else:
                print(f"{package}\t{response.status_code}")
        except Exception:
            print(f"{package}\t{response.status_code if 'response' in locals() else 500}")

if __name__ == "__main__":
    main()
